import {t as uiText} from "./i18n.js";
export function historyNames(state){return [...new Set([...(state.taskNames||[]),...state.tasks.map(t=>t.text),...state.sessions.filter(s=>s.taskId).map(s=>s.name)])].filter(n=>n&&!state.hiddenNames?.includes(n));}
export function newOnce(text,day,id){return{id,text,kind:'once',day,done:[]};}
export function queueGrowth(seconds,queue,make){seconds=Math.max(0,seconds);let used=0,index=0,added=false;while(index<10000){if(!queue[index]){queue.push(make(index));added=true;}const p=queue[index],goal=p.goal*60;if(seconds-used<goal)return{index,plant:p,seconds:seconds-used,ratio:(seconds-used)/goal,completed:index,stage:Math.min(3,Math.floor((seconds-used)/goal*4)),used,added};used+=goal;index++;}return{index:9999,plant:queue[9999],seconds:0,ratio:1,completed:10000,stage:4,used,added};}
export function validatePack(raw){if(raw?.version!==1||!Array.isArray(raw.plants)||raw.plants.length<1||raw.plants.length>12)throw Error(uiText("作物包需有 1 到 12 種植物。"));return raw.plants.map((p,i)=>{if(typeof p.name!=='string'||!p.name.trim()||p.name.length>50||!Number.isFinite(p.goal)||p.goal<1||p.goal>240||!Array.isArray(p.images)||p.images.length!==5||p.images.some(s=>typeof s!=='string'||s.length>350000||!/^data:image\/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/=]+$/.test(s)))throw Error(uiText("每種作物需有名稱、1–240 分鐘，及五張 PNG / JPEG / GIF / WebP 圖片。"));if(p.fruit!==undefined&&(typeof p.fruit!=='string'||p.fruit.length>350000||!/^data:image\/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/=]+$/.test(p.fruit)))throw Error(uiText("收穫物圖片格式不符"));return{name:p.name.trim(),short:p.name.trim(),goal:p.goal,images:[...p.images],fruit:p.fruit};});}

export function groupedHarvest(indices,plantFor){const groups=new Map();for(const index of indices){const p=plantFor(index),key=p.cropId||p.assetKey||p.short||p.name;if(!groups.has(key))groups.set(key,{plant:p,indices:[],count:0});const group=groups.get(key);group.indices.push(index);group.count++;}return [...groups.values()];}
export function settleHarvest(state,indices,day,at=Date.now()){const claimed=new Set(state.claimed);const events=state.harvests||[];for(const index of indices){if(!claimed.has(index)){claimed.add(index);events.push({index,day,at});}}return{claimed:[...claimed].sort((a,b)=>a-b),harvests:events};}
